<template><div class="page"><div class="page-head"><div><h1 class="page-title">粉丝管理</h1><div class="page-subtitle">查看并筛选当前公众号关注用户</div></div><div class="toolbar"><el-input v-model="query.nickname" placeholder="昵称" clearable @change="load"/><el-select v-model="tagFilter" placeholder="按标签筛选" multiple collapse-tags clearable style="width:220px" @change="load"><el-option v-for="tag in tags" :key="tag.id" :label="tag.name" :value="tag.id"/></el-select><el-button @click="load">刷新</el-button><el-button type="primary" @click="sync">同步粉丝</el-button><el-button :disabled="!selected.length" @click="openTagDialog(selected)">批量打标签（{{selected.length}}）</el-button></div></div><div class="surface table-surface"><el-table :data="list" v-loading="loading" @selection-change="rows=>selected=rows"><el-table-column type="selection" width="48"/><el-table-column label="头像" width="72"><template #default="{row}"><el-avatar :src="row.headimgurl">{{(row.nickname||row.openid||'?').slice(0,1)}}</el-avatar></template></el-table-column><el-table-column prop="nickname" label="昵称"><template #default="{row}"><span v-if="row.nickname">{{row.nickname}}</span><span v-else class="muted">未授权</span></template></el-table-column><el-table-column prop="openid" label="OpenID" show-overflow-tooltip/><el-table-column label="性别" width="70"><template #default="{row}">{{['未知','男','女'][row.sex]||'未知'}}</template></el-table-column><el-table-column prop="city" label="城市"><template #default="{row}"><span v-if="row.city||row.province">{{row.province}}{{row.city}}</span><span v-else class="muted">未授权</span></template></el-table-column><el-table-column prop="subscribeScene" label="关注来源" width="100" show-overflow-tooltip/><el-table-column prop="qrSceneStr" label="场景值" width="120" show-overflow-tooltip/><el-table-column prop="remark" label="备注" width="120" show-overflow-tooltip/><el-table-column prop="subscribeTime" label="关注时间"/><el-table-column label="标签" width="200"><template #default="{row}"><el-tag v-for="name in row.tagNames||[]" :key="name" size="small" style="margin-right:4px">{{name}}</el-tag></template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="openTagDialog([row])">打标签</el-button></template></el-table-column></el-table><div class="pager"><el-pagination layout="prev,pager,next" :total="total" :page-size="query.limit" @current-change="page=>{query.page=page;load()}"/></div></div><el-dialog v-model="tagDialog" title="设置标签" width="420"><el-checkbox-group v-model="checkedTagIds"><div v-for="tag in tags" :key="tag.id"><el-checkbox :value="tag.id">{{tag.name}}</el-checkbox></div></el-checkbox-group><template #footer><el-button @click="tagDialog=false">取消</el-button><el-button type="primary" @click="saveTags">保存</el-button></template></el-dialog></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'@/api/console';const list=ref([]),total=ref(0),loading=ref(false),query=reactive({page:1,limit:10,nickname:''});const tags=ref([]),tagFilter=ref([]),selected=ref([]);const tagDialog=ref(false),checkedTagIds=ref([]),taggingRows=ref([]);async function load(){loading.value=true;try{const params={...query,tagid:tagFilter.value.join(',')||undefined};const r=await api.followers(params);list.value=r.page.list;total.value=r.page.totalCount}finally{loading.value=false}}async function loadTags(){tags.value=(await api.tags()).list||[]}async function sync(){await api.syncFollowers();ElMessage.success('同步任务已启动')}function openTagDialog(rows){if(!rows.length)return;taggingRows.value=rows;const tagIdSets=rows.map(r=>new Set((r.tagidList||[]).map(Number)));checkedTagIds.value=tags.value.filter(t=>tagIdSets.every(s=>s.has(t.id))).map(t=>t.id);tagDialog.value=true}async function saveTags(){const rows=taggingRows.value;const beforeIds=new Set();rows.forEach(r=>(r.tagidList||[]).forEach(id=>beforeIds.add(Number(id))));const afterIds=new Set(checkedTagIds.value);const openidList=rows.map(r=>r.openid);const toAdd=[...afterIds].filter(id=>!beforeIds.has(id));const toRemove=[...beforeIds].filter(id=>!afterIds.has(id));for(const tagid of toAdd){await api.batchTag({tagid,openidList})}for(const tagid of toRemove){await api.batchUnTag({tagid,openidList})}tagDialog.value=false;ElMessage.success('已保存');load()}onMounted(async()=>{await loadTags();await load()})</script><style scoped>.pager{display:flex;justify-content:flex-end;margin-top:16px}</style>
